def pbStartForgetScene(party, partyindex, move_to_learn)
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  @party      = party
  @partyindex = partyindex
  @pokemon    = @party[@partyindex]
  @page = 4
  @typebitmap = AnimatedBitmap.new(_INTL("Graphics/UI/types"))
  @sprites = {}
  @sprites["background"] = IconSprite.new(0, 0, @viewport)
  @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
  pbSetSystemFont(@sprites["overlay"].bitmap)
  @sprites["pokeicon"] = PokemonIconSprite.new(@pokemon, @viewport)
  @sprites["pokeicon"].setOffset(PictureOrigin::CENTER)
  @sprites["pokeicon"].x       = 46
  @sprites["pokeicon"].y       = 92
  @sprites["movesel"] = MoveSelectionSprite.new(@viewport, !move_to_learn.nil?)
  @sprites["movesel"].visible = false
  @sprites["movesel"].visible = true
  @sprites["movesel"].index   = 0
  new_move = (move_to_learn) ? Pokemon::Move.new(move_to_learn) : nil
  drawSelectedMove(new_move, @pokemon.moves[0])
  pbFadeInAndShow(@sprites)
end

def pbStartForgetScreen(party, partyindex, move_to_learn)
  ret = -1
  @scene.pbStartForgetScene(party, partyindex, move_to_learn)
  loop do
    ret = @scene.pbChooseMoveToForget(move_to_learn)
    break if ret < 0 || !move_to_learn
    break if $DEBUG || !party[partyindex].moves[ret].hidden_move?
    pbMessage(_INTL("HM moves can't be forgotten now.")) { @scene.pbUpdate }
  end
  @scene.pbEndScene
  return ret
end

def pbEndScene
  pbFadeOutAndHide(@sprites) { pbUpdate }
  pbDisposeSpriteHash(@sprites)
  @typebitmap.dispose
  @markingbitmap&.dispose
  @viewport.dispose
end

def initialize(pokemon, viewport = nil)
  super(viewport)
  @selected      = false
  @active        = false
  @frames_count  = 0
  @current_frame = 0
  self.pokemon   = pokemon
  @logical_x     = 0   # Actual x coordinate
  @logical_y     = 0   # Actual y coordinate
  @adjusted_x    = 0   # Offset due to "jumping" animation in party screen
  @adjusted_y    = 0   # Offset due to "jumping" animation in party screen
end

def pokemon=(value)
  @pokemon = value
  @animBitmap&.dispose
  @animBitmap = nil
  if !@pokemon
    self.bitmap = nil
    @current_frame = 0
    return
  end
  @animBitmap = AnimatedBitmap.new(GameData::Species.icon_filename_from_pokemon(value))
  self.bitmap = @animBitmap.bitmap
  self.src_rect.width  = @animBitmap.height
  self.src_rect.height = @animBitmap.height
  @frames_count = @animBitmap.width / @animBitmap.height
  @current_frame = 0 if @current_frame >= @frames_count
  changeOrigin
end

def self.icon_filename_from_pokemon(pkmn)
  return self.icon_filename(pkmn.species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?, pkmn.egg?)
end

def form=(value)
  oldForm = @form
  @form = value
  @ability = nil
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def calc_stats
  base_stats = self.baseStats
  this_level = self.level
  this_IV    = self.calcIV
  # Format stat multipliers due to nature
  nature_mod = {}
  GameData::Stat.each_main { |s| nature_mod[s.id] = 100 }
  this_nature = self.nature_for_stats
  if this_nature
    this_nature.stat_changes.each { |change| nature_mod[change[0]] += change[1] }
  end
  # Calculate stats
  stats = {}
  GameData::Stat.each_main do |s|
    if s.id == :HP
      stats[s.id] = calcHP(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id])
    else
      stats[s.id] = calcStat(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id], nature_mod[s.id])
    end
  end
  hp_difference = stats[:HP] - @totalhp
  @totalhp = stats[:HP]
  self.hp = [@hp + hp_difference, 1].max if @hp > 0 || hp_difference > 0
  @attack  = stats[:ATTACK]
  @defense = stats[:DEFENSE]
  @spatk   = stats[:SPECIAL_ATTACK]
  @spdef   = stats[:SPECIAL_DEFENSE]
  @speed   = stats[:SPEED]
end

def species_data
  return GameData::Species.get_species_form(@species, form_simple)
end

def hasMove?(move_id)
  move_data = GameData::Move.try_get(move_id)
  return false if !move_data
  return @moves.any? { |m| m.id == move_data.id }
end

MultipleForms.register(:FURFROU, {
  "getForm" => proc { |pkmn|
    if !pkmn.time_form_set ||
       pbGetTimeNow.to_i > pkmn.time_form_set.to_i + (60 * 60 * 24 * 5)   # 5 days
      next 0
    end
  },
  "onSetForm" => proc { |pkmn, form, oldForm|
    pkmn.time_form_set = (form > 0) ? pbGetTimeNow.to_i : nil
  }
})

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end
